from collections import Counter


def transform(grid):
    """Compress 3x3 patches to the distinctive color (excluding 0 and 5)."""
    h, w = len(grid), len(grid[0])
    out = []
    for r in range(0, h, 3):
        row = []
        for c in range(0, w, 3):
            counts = Counter(
                grid[i][j]
                for i in range(r, min(r + 3, h))
                for j in range(c, min(c + 3, w))
                if grid[i][j] not in (0, 5)
            )
            row.append(counts.most_common(1)[0][0] if counts else 0)
        out.append(row)
    return out


if __name__ == '__main__':
    test = [
        [5,8,5,5,5,5,8,8,8],
        [8,5,5,5,5,5,8,8,5],
        [8,8,5,0,0,0,8,5,8],
        [0,0,0,8,8,8,0,0,0],
        [5,5,0,8,5,5,0,5,0],
        [0,0,5,5,8,5,5,0,0],
        [5,0,0,5,3,3,3,3,5],
        [0,0,0,5,3,5,3,5,5],
        [0,0,0,5,3,3,3,3,3],
    ]
    print(transform(test))
    assert transform(test) == [[8,0,8],[0,8,0],[0,3,3]]
